package com.college.attendance.controller;
import com.college.attendance.dto.ComplaintRequest; import com.college.attendance.entity.*; import com.college.attendance.repo.*; import org.springframework.security.access.AccessDeniedException; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/academic") public class AcademicController {
 private final UserRepository users; private final TeacherRepository teachers; private final StudentRepository students; private final SubjectRepository subjects; private final AssignmentRepository assignments; private final SubmissionRepository submissions; private final FeedbackComplaintRepository complaints;
 public AcademicController(UserRepository u,TeacherRepository t,StudentRepository s,SubjectRepository sub,AssignmentRepository a,SubmissionRepository ss,FeedbackComplaintRepository c){users=u;teachers=t;students=s;subjects=sub;assignments=a;submissions=ss;complaints=c;}
 private User user(){return users.findByEmail(SecurityContextHolder.getContext().getAuthentication().getName()).orElseThrow();}
 @GetMapping("/assignments") @PreAuthorize("hasAnyRole('STUDENT','TEACHER')") public List<Assignment> allAssignments(){User u=user(); if(u.getRole()==Role.STUDENT){Student s=students.findByUser(u).orElseThrow();return assignments.findBySubjectIn(subjects.findBySection(s.getSection()));} Teacher t=teachers.findByUser(u).orElseThrow();return assignments.findBySubjectIn(subjects.findByTeacher(t));}
 @PostMapping("/assignments") @PreAuthorize("hasRole('TEACHER')") public Assignment create(@RequestBody Assignment a){Teacher t=teachers.findByUser(user()).orElseThrow(); if(a.getSubject()==null||a.getSubject().getId()==null)throw new IllegalArgumentException("subject required"); Subject subject=subjects.findById(a.getSubject().getId()).orElseThrow(); if(!subject.getTeacher().getId().equals(t.getId()))throw new AccessDeniedException("You do not own this subject"); a.setSubject(subject);a.setTeacher(t);return assignments.save(a);}
 @PostMapping("/assignments/{id}/submit") @PreAuthorize("hasRole('STUDENT')") public Submission submit(@PathVariable Long id,@RequestBody Submission s){Student st=students.findByUser(user()).orElseThrow(); Assignment assignment=assignments.findById(id).orElseThrow(); if(!assignment.getSubject().getSection().equals(st.getSection()))throw new AccessDeniedException("Assignment is not assigned to your section");s.setAssignment(assignment);s.setStudent(st);s.setSubmittedAt(LocalDateTime.now());return submissions.save(s);}
 @GetMapping("/submissions") @PreAuthorize("hasAnyRole('STUDENT','TEACHER')") public List<Submission> submissions(){User u=user(); if(u.getRole()==Role.STUDENT)return submissions.findByStudent(students.findByUser(u).orElseThrow()); return submissions.findByAssignmentTeacher(teachers.findByUser(u).orElseThrow());}
 @PostMapping("/complaints") @PreAuthorize("isAuthenticated()") public FeedbackComplaint complaint(@RequestBody ComplaintRequest r){return complaints.save(FeedbackComplaint.builder().raisedBy(user()).type(r.getType()).subject(r.getSubject()).message(r.getMessage()).status("OPEN").createdAt(LocalDateTime.now()).build());}
 @GetMapping("/complaints/mine") @PreAuthorize("isAuthenticated()") public List<FeedbackComplaint> mine(){return complaints.findByRaisedBy(user());}
 @PostMapping("/complaints/{id}/resolve") @PreAuthorize("hasRole('HOD')") public FeedbackComplaint resolve(@PathVariable Long id,@RequestBody Map<String,String> body){FeedbackComplaint c=complaints.findById(id).orElseThrow();c.setStatus("RESOLVED");c.setResolution(body.getOrDefault("resolution","Resolved"));c.setResolvedAt(LocalDateTime.now());return complaints.save(c);}
}
